/** Fixed target ablation: only sourceImage.probability differs between arms. */
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {prepare,design} from '../../../static/inverse/core/engine.js';
import {referenceError} from '../../../static/inverse/core/image-reference.js';
import {auditFeatureFidelity} from '../../../static/inverse/core/feature-shapes.js';
import {renderExportedWeave} from '../../../scripts/inverse/export-renderer.mjs';

const root=new URL('.',import.meta.url),read=async p=>JSON.parse(await fs.readFile(p));
const hash=b=>createHash('sha256').update(b).digest('hex');
const [id,method]=process.argv.slice(2);assert.ok(['binary','soft'].includes(method));
const inputs=await read(new URL('inputs.json',root)),entry=inputs.rows.find(r=>r.id===id);assert.ok(entry);
const pins=await read(new URL('source.json',root));
const verify=async()=>{for(const [p,h]of Object.entries(pins))assert.equal(hash(await fs.readFile(p)),h,p);};
await verify();
async function asset(name){const a=entry.assets[name],bytes=await fs.readFile(a.path);assert.equal(hash(bytes),a.sha256);return bytes;}
const mask=Uint8Array.from(await asset('mask.bin')),bytes=await asset('probability.f32'),n=entry.resolution;
assert.equal(bytes.length,n*n*4);assert.equal(mask.length,n*n);
const probability=Float32Array.from({length:n*n},(_,i)=>bytes.readFloatLE(4*i));
assert.ok(probability.every((p,i)=>Number.isFinite(p)&&p>=0&&p<=1&&Number(p>=.5)===mask[i]));
const folder=new URL(id+'/'+method+'/',root);await fs.mkdir(folder,{recursive:true});
const sourceMask=mask.slice(),started=performance.now();
const prepared=prepare({type:'mask',mask,resolution:n},{...inputs.configuration,invert:false,removeSpecks:0,fillHoles:0});
if(method==='soft')prepared.target.sourceImage.probability=probability.slice();
assert.deepEqual(prepared.target.sourceImage.mask,sourceMask);
const row={id,method,kind:entry.kind,sourceId:entry.sourceId,maskSha256:hash(sourceMask),
  probabilitySha256:hash(new Uint8Array(prepared.target.sourceImage.probability.buffer)),assets:{}};
const store=async(name,data)=>{await fs.writeFile(new URL(name,folder),data);row.assets[name]={sha256:hash(data)};};
try{
  const ready=performance.now();
  const result=await design(prepared.target,inputs.configuration,()=>{}),finished=performance.now();
  row.prepareSeconds=(ready-started)/1000;row.solveSeconds=(finished-ready)/1000;row.totalSeconds=(finished-started)/1000;
  assert.deepEqual(prepared.target.sourceImage.mask,sourceMask,'Fitting may not change the target.');
  for(const name of ['cut_geometry.json','template_left.svg','template_right.svg','weave_preview.svg'])await store(name,result.files[name]);
  await store('engine-report.json',JSON.stringify(result.report,null,2)+'\n');
  const woven=await renderExportedWeave(result.files['cut_geometry.json'],n);await store('woven.png',woven.png);
  row.targetError=referenceError(prepared.target.sourceImage,woven.mask);
  row.features=auditFeatureFidelity(prepared.target.sourceImage,woven.mask,result.report.settings);
  row.templateChecksPassed=result.report.templateChecksPassed;row.geometryPassed=result.report.validation.passed;row.paperStatus=result.report.manufacturing.status;
  row.checkedDerivedMask=row.templateChecksPassed&&row.features.passed&&row.targetError.mismatchFraction<=result.report.settings.maxImageError;
  row.selectedCounts=result.report.solver.selectedCounts;row.status=row.checkedDerivedMask?'checked-derived-mask':'review-required';
  // Exact synthetic truth enters only after design and independent rendering.
  if(entry.assets['truth.bin']){
    const truth=Uint8Array.from(await asset('truth.bin'));
    row.syntheticTruthError=referenceError({mask:truth,resolution:n},woven.mask);
    row.syntheticTruthFeatures=auditFeatureFidelity({mask:truth,resolution:n},woven.mask,result.report.settings);
    const geometry=inputs.syntheticGeometry.find(g=>g.sourceId===entry.sourceId);assert.ok(geometry);
    const fineN=1600,ideal=Uint8Array.from({length:fineN*fineN},(_,i)=>{
      const x=(i%fineN+.5)*400/fineN,y=(Math.floor(i/fineN)+.5)*400/fineN;
      return (geometry.verticalCutsCropPixels.filter(v=>v<=x).length+geometry.horizontalCutsCropPixels.filter(v=>v<=y).length)%2;
    });
    const fine=await renderExportedWeave(result.files['cut_geometry.json'],fineN);
    row.syntheticFineGridError={resolution:fineN,...referenceError({mask:ideal,resolution:fineN},fine.mask),
      scope:'Independent SVG samples against the known continuous straight checker at finer resolution; a finite image-error estimate, not a certificate of exact point contacts.'};
  }
}catch(error){row.status='failed';row.error=error.message;row.totalSeconds=(performance.now()-started)/1000;if(error.report)await store('engine-report.json',JSON.stringify(error.report,null,2)+'\n');}
await verify();await fs.writeFile(new URL('result.json',folder),JSON.stringify(row,null,2)+'\n');
console.log(JSON.stringify({id,method,status:row.status,seconds:row.totalSeconds,targetError:row.targetError?.mismatchFraction,truthError:row.syntheticTruthError?.mismatchFraction,error:row.error}));

import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {materialMask} from '../material-corrected-scenes-v1/material-fields.mjs';
import {prepare} from '../../../static/inverse/core/engine.js';
const root=new URL('.',import.meta.url),read=async p=>JSON.parse(await fs.readFile(p));
const inputs=await read(new URL('inputs.json',root)),study=new URL('../material-corrected-scenes-v1/',root);
const probe=await read(new URL('probe/manifest.json',study)),pipeline=await read(new URL('pipeline/report.json',study));
const rows=[];
for(const entry of inputs.rows){
  const mask=Uint8Array.from(await fs.readFile(entry.assets['mask.bin'].path));
  const bytes=await fs.readFile(entry.assets['probability.f32'].path),p=Float32Array.from({length:400**2},(_,i)=>bytes.readFloatLE(4*i));
  const prepared=prepare({type:'mask',mask,resolution:400},inputs.configuration);
  assert.deepEqual(prepared.target.sourceImage.mask,mask);
  assert.ok(p.every((v,i)=>Number.isFinite(v)&&v>=0&&v<=1&&Number(v>=.5)===mask[i]));
  const row={id:entry.id,maskPreparedExactly:true};
  if(entry.kind==='held-out-learned-field'){
    const source=probe.rows.find(s=>s.id===entry.sourceId),run=pipeline.rows.find(s=>s.id===entry.sourceId&&s.method==='candidate-joint');
    const b=await fs.readFile(new URL('probe/'+source.assets.candidate.material.path,study));
    const f=Float32Array.from({length:256**2},(_,i)=>b.readFloatLE(4*i));
    const actual=materialMask(f,256,source.window,run.selectedCrop.quad,400);assert.deepEqual(actual.mask,mask);
    let max=0;for(let i=0;i<p.length;i++)max=Math.max(max,Math.abs(actual.probability[i]-p[i]));
    assert.equal(max,0);row.maximumDifferenceFromOriginalJSSampler=max;
  }
  if(entry.kind==='native-400-exact-checker')assert.deepEqual(p,Float32Array.from(mask));
  rows.push(row);
}
await fs.writeFile(new URL('preflight.json',root),JSON.stringify({status:'passed',rows},null,2)+'\n');
console.log('Eight inputs verified; real probabilities exactly match the original JS sampler.');
